"""Reading the three data files: the catalogue, the movements and the orders."""

from __future__ import annotations

import datetime
import re
from dataclasses import dataclass, field
from decimal import Decimal
from typing import Dict, Iterator, List, Optional, Tuple

__all__ = [
    "ParseError",
    "Product",
    "Movement",
    "Order",
    "TAX_RATES",
    "parse_catalog",
    "parse_movements",
    "parse_orders",
    "parse_date",
    "parse_sku",
    "counting_order",
    "check_stock",
    "StockError",
]

# Whitespace, as far as the files are concerned: spaces and tabs.
_WS = " \t"
_SPLIT = re.compile(r"[ \t]+")

_SKU = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
_PRICE = re.compile(r"([0-9]+)(?:\.([0-9]{1,2}))?")
_WHOLE = re.compile(r"[0-9]+")
_SIGNED = re.compile(r"[+-]?[0-9]+")
_DATE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")
_ORDER_ID = re.compile(r"[Ss][Oo]-([0-9]+)")
_ORDER_LINE = re.compile(r"([^*]*)\*(.*)")
_MOVEMENT = re.compile(r"([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*))?")

#: Tax rate of each tax band, as a percentage.
TAX_RATES = {"standard": 20, "reduced": 5, "zero": 0}


class ParseError(ValueError):
    """A line of a data file that does not follow the rules.

    ``line`` is the line number, counting from 1 (blank and comment lines
    included).  The message always mentions ``line N``.
    """

    def __init__(self, line: int, reason: str):
        self.line = line
        self.reason = reason
        super().__init__(f"line {line}: {reason}")


class StockError(ParseError):
    """A movement that takes the stock of a product below zero."""

    def __init__(self, line: int, sku: str, date: datetime.date, balance: int, index: int):
        self.sku = sku
        self.date = date
        self.balance = balance
        self.index = index
        super().__init__(
            line, f"stock of {sku} would go below zero on {date.isoformat()} ({balance})"
        )


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str = "standard"


@dataclass(frozen=True)
class Movement:
    date: datetime.date
    sku: str
    quantity: int
    note: str = ""
    line: int = field(default=0, compare=False, repr=False)


@dataclass
class Order:
    id: str
    date: datetime.date
    customer: str
    lines: List[Tuple[str, int]]
    line: int = field(default=0, compare=False, repr=False)


# --------------------------------------------------------------------------
# helpers


def _lines(text: str) -> Iterator[Tuple[int, str]]:
    """Yield ``(number, content)`` for each line that is not blank or a comment.

    A line ends at LF or CRLF and nowhere else; a leading byte order mark is
    ignored.  The content has spaces and tabs trimmed from both ends.
    """
    if text.startswith("﻿"):
        text = text[1:]
    pieces = text.split("\n")
    last = len(pieces) - 1
    for index, raw in enumerate(pieces):
        if index < last and raw.endswith("\r"):
            raw = raw[:-1]
        content = raw.strip(_WS)
        if not content or content.startswith("#"):
            continue
        yield index + 1, content


def _show(value: str) -> str:
    return repr(value)


def parse_date(value: str) -> Optional[datetime.date]:
    """``YYYY-MM-DD`` as a date, or ``None`` when it is not a real date."""
    m = _DATE.fullmatch(value)
    if not m:
        return None
    try:
        return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        return None


def parse_sku(value: str) -> Optional[str]:
    """A SKU in upper case, or ``None`` when it is not shaped like one."""
    if _SKU.fullmatch(value):
        return value.upper()
    return None


def _date(n: int, value: str) -> datetime.date:
    d = parse_date(value)
    if d is None:
        if _DATE.fullmatch(value):
            raise ParseError(n, f"no such date {_show(value)}")
        raise ParseError(n, f"bad date {_show(value)} (expected YYYY-MM-DD)")
    return d


def _known_sku(n: int, value: str, catalog: Dict[str, Product]) -> str:
    sku = parse_sku(value)
    if sku is None:
        raise ParseError(n, f"bad SKU {_show(value)}")
    if sku not in catalog:
        raise ParseError(n, f"unknown SKU {sku}")
    return sku


def _money(pennies: int) -> Decimal:
    sign = "-" if pennies < 0 else ""
    pennies = abs(pennies)
    return Decimal(f"{sign}{pennies // 100}.{pennies % 100:02d}")


# --------------------------------------------------------------------------
# the catalogue


def parse_catalog(text: str) -> Dict[str, Product]:
    """Read ``catalog.txt``: a dict of SKU (upper case) to :class:`Product`."""
    catalog: Dict[str, Product] = {}
    for n, content in _lines(text):
        fields = [f.strip(_WS) for f in content.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(
                n, f"expected 4 or 5 fields separated by '|', found {len(fields)}"
            )
        sku_text, name, price_text, reorder_text = fields[:4]

        sku = parse_sku(sku_text)
        if sku is None:
            raise ParseError(n, f"bad SKU {_show(sku_text)}")
        if sku in catalog:
            raise ParseError(n, f"duplicate SKU {sku}")

        if not name:
            raise ParseError(n, "empty name")

        m = _PRICE.fullmatch(price_text)
        if not m:
            raise ParseError(n, f"bad price {_show(price_text)}")
        pennies = int(m.group(1)) * 100 + int((m.group(2) or "0").ljust(2, "0"))
        if pennies < 1:
            raise ParseError(n, f"bad price {_show(price_text)} (must be at least 0.01)")

        if not _WHOLE.fullmatch(reorder_text):
            raise ParseError(n, f"bad reorder level {_show(reorder_text)}")
        reorder = int(reorder_text)

        tax = "standard"
        if len(fields) == 5:
            tax = fields[4].lower()
            if tax not in TAX_RATES:
                raise ParseError(
                    n, f"bad tax band {_show(fields[4])} (expected standard, reduced or zero)"
                )

        catalog[sku] = Product(sku, name, _money(pennies), reorder, tax)
    return catalog


# --------------------------------------------------------------------------
# the movements


def counting_order(movements: List[Movement]) -> List[Movement]:
    """The movements in the order they count: by date, ties in list order."""
    return sorted(movements, key=lambda m: m.date)


def check_stock(movements: List[Movement]) -> None:
    """Raise :class:`StockError` for the first movement taking stock below zero."""
    order = sorted(range(len(movements)), key=lambda i: movements[i].date)
    balance: Dict[str, int] = {}
    for i in order:
        m = movements[i]
        b = balance.get(m.sku, 0) + m.quantity
        if b < 0:
            raise StockError(m.line, m.sku, m.date, b, i)
        balance[m.sku] = b


def parse_movements(text: str, catalog: Dict[str, Product]) -> List[Movement]:
    """Read ``movements.txt``: a list of :class:`Movement` in file order."""
    movements: List[Movement] = []
    for n, content in _lines(text):
        m = _MOVEMENT.fullmatch(content)
        if not m:
            raise ParseError(n, "expected DATE SKU QUANTITY [NOTE]")
        date_text, sku_text, qty_text, note = m.groups()
        date = _date(n, date_text)
        sku = _known_sku(n, sku_text, catalog)
        if not _SIGNED.fullmatch(qty_text):
            raise ParseError(n, f"bad quantity {_show(qty_text)}")
        quantity = int(qty_text)
        if quantity == 0:
            raise ParseError(n, "quantity may not be zero")
        movements.append(Movement(date, sku, quantity, note or "", n))
    check_stock(movements)
    return movements


# --------------------------------------------------------------------------
# the orders


def parse_orders(text: str, catalog: Dict[str, Product]) -> List[Order]:
    """Read ``orders.txt``: a list of :class:`Order` in file order."""
    orders: List[Order] = []
    seen = set()
    for n, content in _lines(text):
        fields = _SPLIT.split(content)
        if len(fields) != 4:
            raise ParseError(n, "expected ORDER DATE CUSTOMER LINES")
        id_text, date_text, customer, lines_text = fields

        if not _ORDER_ID.fullmatch(id_text):
            raise ParseError(n, f"bad order number {_show(id_text)}")
        order_id = id_text.upper()
        if order_id in seen:
            raise ParseError(n, f"duplicate order {order_id}")

        date = _date(n, date_text)

        lines: List[Tuple[str, int]] = []
        skus = set()
        for piece in lines_text.split(","):
            lm = _ORDER_LINE.fullmatch(piece)
            if not lm:
                raise ParseError(n, f"bad order line {_show(piece)} (expected SKU*QUANTITY)")
            sku = _known_sku(n, lm.group(1), catalog)
            if sku in skus:
                raise ParseError(n, f"{sku} appears more than once in the order")
            qty_text = lm.group(2)
            if not _WHOLE.fullmatch(qty_text) or int(qty_text) < 1:
                raise ParseError(n, f"bad quantity {_show(qty_text)} for {sku}")
            skus.add(sku)
            lines.append((sku, int(qty_text)))

        seen.add(order_id)
        orders.append(Order(order_id, date, customer, lines, n))
    return orders

