# --------------------------------------------------------------------------
# the catalogue


def parse_catalog(text: str) -> Dict[str, Product]:
    """Read ``catalog.txt``: a dict of SKU (upper case) to :class:`Product`."""
    catalog: Dict[str, Product] = {}
    for n, content in _lines(text):
        fields = [f.strip(_WS) for f in content.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(
                n, f"expected 4 or 5 fields separated by '|', found {len(fields)}"
            )
        sku_text, name, price_text, reorder_text = fields[:4]

        sku = parse_sku(sku_text)
        if sku is None:
            raise ParseError(n, f"bad SKU {_show(sku_text)}")
        if sku in catalog:
            raise ParseError(n, f"duplicate SKU {sku}")

        if not name:
            raise ParseError(n, "empty name")

        m = _PRICE.fullmatch(price_text)
        if not m:
            raise ParseError(n, f"bad price {_show(price_text)}")
        pennies = int(m.group(1)) * 100 + int((m.group(2) or "0").ljust(2, "0"))
        if pennies < 1:
            raise ParseError(n, f"bad price {_show(price_text)} (must be at least 0.01)")

        if not _WHOLE.fullmatch(reorder_text):
            raise ParseError(n, f"bad reorder level {_show(reorder_text)}")
        reorder = int(reorder_text)

        tax = "standard"
        if len(fields) == 5:
            tax = fields[4].lower()
            if tax not in TAX_RATES:
                raise ParseError(
                    n, f"bad tax band {_show(fields[4])} (expected standard, reduced or zero)"
                )

        catalog[sku] = Product(sku, name, _money(pennies), reorder, tax)
    return catalog


# --------------------------------------------------------------------------
# the movements


def counting_order(movements: List[Movement]) -> List[Movement]:
    """The movements in the order they count: by date, ties in list order."""
    return sorted(movements, key=lambda m: m.date)


def check_stock(movements: List[Movement]) -> None:
    """Raise :class:`StockError` for the first movement taking stock below zero."""
    order = sorted(range(len(movements)), key=lambda i: movements[i].date)
    balance: Dict[str, int] = {}
    for i in order:
        m = movements[i]
        b = balance.get(m.sku, 0) + m.quantity
        if b < 0:
            raise StockError(m.line, m.sku, m.date, b, i)
        balance[m.sku] = b


def parse_movements(text: str, catalog: Dict[str, Product]) -> List[Movement]:
    """Read ``movements.txt``: a list of :class:`Movement` in file order."""
    movements: List[Movement] = []
    for n, content in _lines(text):
        m = _MOVEMENT.fullmatch(content)
        if not m:
            raise ParseError(n, "expected DATE SKU QUANTITY [NOTE]")
        date_text, sku_text, qty_text, note = m.groups()
        date = _date(n, date_text)
        sku = _known_sku(n, sku_text, catalog)
        if not _SIGNED.fullmatch(qty_text):
            raise ParseError(n, f"bad quantity {_show(qty_text)}")
        quantity = int(qty_text)
        if quantity == 0:
            raise ParseError(n, "quantity may not be zero")
        movements.append(Movement(date, sku, quantity, note or "", n))
    check_stock(movements)
    return movements


# --------------------------------------------------------------------------
# the orders


def parse_orders(text: str, catalog: Dict[str, Product]) -> List[Order]:
    """Read ``orders.txt``: a list of :class:`Order` in file order."""
    orders: List[Order] = []
    seen = set()
    for n, content in _lines(text):
        fields = _SPLIT.split(content)
        if len(fields) != 4:
            raise ParseError(n, "expected ORDER DATE CUSTOMER LINES")
        id_text, date_text, customer, lines_text = fields

        if not _ORDER_ID.fullmatch(id_text):
            raise ParseError(n, f"bad order number {_show(id_text)}")
        order_id = id_text.upper()
        if order_id in seen:
            raise ParseError(n, f"duplicate order {order_id}")

        date = _date(n, date_text)

        lines: List[Tuple[str, int]] = []
        skus = set()
        for piece in lines_text.split(","):
            lm = _ORDER_LINE.fullmatch(piece)
            if not lm:
                raise ParseError(n, f"bad order line {_show(piece)} (expected SKU*QUANTITY)")
            sku = _known_sku(n, lm.group(1), catalog)
            if sku in skus:
                raise ParseError(n, f"{sku} appears more than once in the order")
            qty_text = lm.group(2)
            if not _WHOLE.fullmatch(qty_text) or int(qty_text) < 1:
                raise ParseError(n, f"bad quantity {_show(qty_text)} for {sku}")
            skus.add(sku)
            lines.append((sku, int(qty_text)))

        seen.add(order_id)
        orders.append(Order(order_id, date, customer, lines, n))
    return orders

