"""The shelves: stock levels, what is low, a product's history."""

from __future__ import annotations

import datetime
from typing import Dict, List, Tuple

from .parsing import Movement, Product, counting_order

__all__ = [
    "stock_levels",
    "stock_status",
    "buy_quantity",
    "history",
    "shippable",
]


def stock_levels(catalog: Dict[str, Product], movements: List[Movement]) -> Dict[str, int]:
    """SKU to quantity on the shelf, for every product in the catalogue."""
    levels = {sku: 0 for sku in catalog}
    for m in movements:
        if m.sku in levels:
            levels[m.sku] += m.quantity
    return levels


def stock_status(onhand: int, reorder: int) -> str:
    """``out`` at zero, ``low`` at or under the reorder level, ``ok`` otherwise."""
    if onhand <= 0:
        return "out"
    if onhand <= reorder:
        return "low"
    return "ok"


def buy_quantity(onhand: int, reorder: int) -> int:
    """How many to buy to get back to twice the reorder level (at least 1)."""
    return max(1, 2 * reorder - onhand)


def history(sku: str, movements: List[Movement]) -> List[Tuple[Movement, int]]:
    """A product's movements in the order they count, each with the balance after it."""
    balance = 0
    rows = []
    for m in counting_order(movements):
        if m.sku == sku:
            balance += m.quantity
            rows.append((m, balance))
    return rows


def shippable(sku: str, movements: List[Movement], date: datetime.date) -> int:
    """How many of a product can go out on ``date`` in a movement added at the end.

    That is no more than the stock after every movement dated on or before
    ``date``, and no more than the lowest stock at any later point.
    """
    balance = 0
    limit = None
    for m in counting_order(movements):
        if m.sku != sku:
            continue
        balance += m.quantity
        if m.date <= date:
            limit = balance
        else:
            if limit is None:
                limit = 0
            limit = min(limit, balance)
    if limit is None:
        limit = balance
    return max(0, limit)

