"""The ``stockroom`` command."""

from __future__ import annotations

import csv
import io
import json
import os
import sys
from typing import Dict, List, Optional

from .orders import (
    Quote,
    invoice_order,
    order_status,
    plan_fulfilment,
    price_order,
    shipment_note,
    shipped_quantities,
)
from .parsing import (
    Movement,
    Order,
    ParseError,
    StockError,
    _MOVEMENT,
    check_stock,
    parse_catalog,
    parse_date,
    parse_movements,
    parse_orders,
    parse_sku,
)
from .shelves import buy_quantity, history, stock_levels, stock_status

USAGE = """\
usage: stockroom [--dir DIR] COMMAND [ARGS]

the shelves:
  stock [--json]                         what is on the shelves
  low [--json]                           what needs buying
  history SKU [--json]                   a product's movements
  receive DATE SKU QUANTITY [NOTE]       record stock coming in
  ship DATE SKU QUANTITY [NOTE]          record stock going out

the orders:
  quote ORDER [--json]                   price an order
  fulfil ORDER DATE                      ship what the shelves can cover
  invoice ORDER [--json]                 price what has shipped
  report [--format text|csv|json]        one row per order
"""

CATALOG = "catalog.txt"
MOVEMENTS = "movements.txt"
ORDERS = "orders.txt"


class UsageError(Exception):
    """Something wrong with the command line (exit 2)."""


class FileProblem(Exception):
    """A file that cannot be read (exit 2)."""


class Refused(Exception):
    """A mistake in a data file, or a request that is refused (exit 1)."""


# --------------------------------------------------------------------------
# the command line

# command: (positional argument names, optional argument names, options)
COMMANDS = {
    "stock": ((), (), {"--json"}),
    "low": ((), (), {"--json"}),
    "history": (("SKU",), (), {"--json"}),
    "receive": (("DATE", "SKU", "QUANTITY"), ("NOTE",), None),
    "ship": (("DATE", "SKU", "QUANTITY"), ("NOTE",), None),
    "quote": (("ORDER",), (), {"--json"}),
    "fulfil": (("ORDER", "DATE"), (), None),
    "invoice": (("ORDER",), (), {"--json"}),
    "report": ((), (), {"--format"}),
}

FORMATS = ("text", "csv", "json")


class Request:
    def __init__(self) -> None:
        self.dir = "."
        self.command = ""
        self.args: List[str] = []
        self.json = False
        self.format = "text"


def parse_command_line(argv: List[str]) -> Request:
    req = Request()

    # --dir may come anywhere on the line, for every command.
    rest: List[str] = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise UsageError("option --dir needs a value")
            req.dir = argv[i + 1]
            i += 2
            continue
        if arg.startswith("--dir="):
            req.dir = arg[len("--dir="):]
        else:
            rest.append(arg)
        i += 1

    position = next((k for k, a in enumerate(rest) if not a.startswith("-")), None)
    if position is None:
        if rest:
            raise UsageError(f"unknown option {rest[0]}")
        raise UsageError("no command given")
    before, command, after = rest[:position], rest[position], rest[position + 1:]
    if command not in COMMANDS:
        raise UsageError(f"unknown command {command!r}")
    req.command = command
    required, optional, options = COMMANDS[command]

    if options is None:
        # receive, ship and fulfil take every argument as typed.
        if before:
            raise UsageError(f"unknown option {before[0]} for {command}")
        positionals = after
    else:
        positionals = []
        words = before + after
        i = 0
        while i < len(words):
            arg = words[i]
            if not arg.startswith("-"):
                positionals.append(arg)
            elif arg == "--json" and "--json" in options:
                req.json = True
            elif "--format" in options and (arg == "--format" or arg.startswith("--format=")):
                if arg == "--format":
                    if i + 1 >= len(words):
                        raise UsageError("option --format needs a value")
                    value = words[i + 1]
                    i += 1
                else:
                    value = arg[len("--format="):]
                if value not in FORMATS:
                    raise UsageError(
                        f"bad value {value!r} for --format (expected text, csv or json)"
                    )
                req.format = value
            else:
                raise UsageError(f"unknown option {arg} for {command}")
            i += 1

    if not len(required) <= len(positionals) <= len(required) + len(optional):
        names = " ".join(list(required) + [f"[{n}]" for n in optional])
        raise UsageError(f"wrong number of arguments: usage: stockroom {command} {names}".rstrip())
    req.args = positionals

    for name, value in zip(required, positionals):
        if name == "DATE" and parse_date(value) is None:
            raise UsageError(f"bad date {value!r} (expected a real date as YYYY-MM-DD)")
    return req


# --------------------------------------------------------------------------
# the files


class Files:
    def __init__(self, directory: str) -> None:
        self.dir = directory

    def path(self, name: str) -> str:
        return os.path.join(self.dir, name)

    def label(self, name: str) -> str:
        return name if self.dir == "." else os.path.join(self.dir, name)

    def read_bytes(self, name: str, required: bool) -> bytes:
        path = self.path(name)
        try:
            with open(path, "rb") as f:
                return f.read()
        except FileNotFoundError:
            if required:
                raise FileProblem(f"{self.label(name)}: file not found")
            return b""
        except IsADirectoryError:
            raise FileProblem(f"{self.label(name)}: is a folder, not a file")
        except OSError as e:
            raise FileProblem(f"{self.label(name)}: cannot read: {e.strerror or e}")

    def read(self, name: str, required: bool) -> str:
        data = self.read_bytes(name, required)
        try:
            return data.decode("utf-8")
        except UnicodeDecodeError as e:
            line = data[: e.start].count(b"\n") + 1
            raise FileProblem(f"{self.label(name)}: line {line}: not valid UTF-8")

    def parse(self, name: str, parser, *args):
        try:
            return parser(*args)
        except ParseError as e:
            raise Refused(f"{self.label(name)}: line {e.line}: {e.reason}")


# --------------------------------------------------------------------------
# formatting


def money(amount) -> str:
    text = str(amount)
    return "0.00" if text == "-0.00" else text


def signed(quantity: int) -> str:
    return f"+{quantity}" if quantity > 0 else str(quantity)


def movement_text(date: str, sku: str, quantity: int, note: str) -> str:
    text = f"{date} {sku} {signed(quantity)}"
    return f"{text} {note}" if note else text


def quote_lines(quote: Quote, prefix: str = "") -> List[str]:
    out = [f"{prefix}{quote.id} {quote.date.isoformat()} {quote.customer}"]
    for line in quote.lines:
        out.append(
            " ".join(
                [
                    line.sku,
                    str(line.quantity),
                    money(line.unit),
                    money(line.gross),
                    money(line.discount),
                    money(line.net),
                ]
            )
        )
    out.append(f"subtotal {money(quote.subtotal)}")
    out.append(f"order discount {money(quote.order_discount)}")
    out.append(f"tax {money(quote.tax)}")
    out.append(f"total {money(quote.total)}")
    return out


def quote_json(quote: Quote) -> dict:
    return {
        "order": quote.id,
        "date": quote.date.isoformat(),
        "customer": quote.customer,
        "lines": [
            {
                "sku": line.sku,
                "quantity": line.quantity,
                "unit": money(line.unit),
                "gross": money(line.gross),
                "discount": money(line.discount),
                "net": money(line.net),
            }
            for line in quote.lines
        ],
        "subtotal": money(quote.subtotal),
        "order_discount": money(quote.order_discount),
        "tax": money(quote.tax),
        "total": money(quote.total),
    }


def as_json(value) -> str:
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def as_lines(lines: List[str]) -> str:
    return "".join(line + "\n" for line in lines)


# --------------------------------------------------------------------------
# the commands


def find_order(orders: List[Order], text: str) -> Order:
    wanted = text.upper()
    for order in orders:
        if order.id == wanted:
            return order
    raise Refused(f"unknown order {text}")


def find_sku(catalog, text: str) -> str:
    sku = parse_sku(text)
    if sku is None or sku not in catalog:
        raise Refused(f"unknown SKU {text}")
    return sku


def run(req: Request) -> str:
    files = Files(req.dir)
    if not os.path.isdir(req.dir):
        raise FileProblem(f"{req.dir}: no such folder")

    command = req.command
    shelves = command in ("stock", "low", "history", "receive", "ship")
    wants_movements = shelves or command in ("fulfil", "invoice", "report")
    wants_orders = command in ("quote", "fulfil", "invoice", "report")

    # Read every file first, then make sense of them.
    catalog_text = files.read(CATALOG, required=True)
    movements_bytes = files.read_bytes(MOVEMENTS, required=False) if wants_movements else b""
    if wants_movements:
        movements_text = files.read(MOVEMENTS, required=False)
    orders_text = files.read(ORDERS, required=False) if wants_orders else ""

    catalog = files.parse(CATALOG, parse_catalog, catalog_text)
    movements: List[Movement] = []
    orders: List[Order] = []
    if wants_movements:
        movements = files.parse(MOVEMENTS, parse_movements, movements_text, catalog)
    if wants_orders:
        orders = files.parse(ORDERS, parse_orders, orders_text, catalog)

    if command == "stock":
        levels = stock_levels(catalog, movements)
        rows = []
        for sku in sorted(catalog):
            p = catalog[sku]
            rows.append(
                {
                    "sku": sku,
                    "name": p.name,
                    "onhand": levels[sku],
                    "status": stock_status(levels[sku], p.reorder),
                }
            )
        if req.json:
            return as_json(rows)
        return as_lines(f"{r['sku']} {r['onhand']} {r['status']} {r['name']}" for r in rows)

    if command == "low":
        levels = stock_levels(catalog, movements)
        rows = []
        for sku in sorted(catalog):
            p = catalog[sku]
            if stock_status(levels[sku], p.reorder) == "ok":
                continue
            rows.append(
                {
                    "sku": sku,
                    "onhand": levels[sku],
                    "reorder": p.reorder,
                    "buy": buy_quantity(levels[sku], p.reorder),
                }
            )
        if req.json:
            return as_json(rows)
        return as_lines(f"{r['sku']} {r['onhand']} {r['reorder']} {r['buy']}" for r in rows)

    if command == "history":
        sku = find_sku(catalog, req.args[0])
        rows = [
            {
                "date": m.date.isoformat(),
                "delta": signed(m.quantity),
                "balance": balance,
                "note": m.note,
            }
            for m, balance in history(sku, movements)
        ]
        if req.json:
            return as_json(rows)
        return as_lines(
            " ".join(x for x in (r["date"], r["delta"], str(r["balance"]), r["note"]) if x)
            for r in rows
        )

    if command in ("receive", "ship"):
        date_text, sku_text, qty_text = req.args[:3]
        note = req.args[3] if len(req.args) > 3 else ""
        sku = find_sku(catalog, sku_text)
        if not (qty_text.isascii() and qty_text.isdigit()) or int(qty_text) < 1:
            raise Refused(f"bad quantity {qty_text!r} (expected a whole number of 1 or more)")
        if "\n" in note or "\r" in note:
            raise Refused("a note may not contain a line break")
        note = note.strip(" \t")
        quantity = int(qty_text) * (1 if command == "receive" else -1)
        line = movement_text(date_text, sku, quantity, note)
        # The line must read back as exactly this movement.
        if _MOVEMENT.fullmatch(line) is None:  # pragma: no cover - defensive
            raise Refused("this movement cannot be written")
        new = Movement(parse_date(date_text), sku, quantity, note, 0)
        try:
            check_stock(movements + [new])
        except StockError as e:
            where = "" if e.index == len(movements) else f" (at {files.label(MOVEMENTS)} line {e.line})"
            raise Refused(
                f"refused: stock of {sku} would go below zero on {e.date.isoformat()}{where}"
            )
        append_lines(files, movements_bytes, [line])
        return as_lines([line])

    if command == "quote":
        order = find_order(orders, req.args[0])
        quote = price_order(order, catalog)
        return as_json(quote_json(quote)) if req.json else as_lines(quote_lines(quote))

    if command == "invoice":
        order = find_order(orders, req.args[0])
        shipped = invoice_order(order, movements)
        if not shipped.lines:
            raise Refused(f"nothing has shipped on order {order.id} yet")
        quote = price_order(shipped, catalog)
        return as_json(quote_json(quote)) if req.json else as_lines(quote_lines(quote, "invoice "))

    if command == "fulfil":
        order = find_order(orders, req.args[0])
        date = parse_date(req.args[1])
        if date < order.date:
            raise Refused(
                f"refused: {date.isoformat()} is before the date of order {order.id} "
                f"({order.date.isoformat()})"
            )
        plan = plan_fulfilment(order, movements, date)
        note = shipment_note(order.id)
        new_lines = [
            movement_text(date.isoformat(), sku, -ship, note) for sku, ship, _ in plan if ship > 0
        ]
        added = [Movement(date, sku, -ship, note) for sku, ship, _ in plan if ship > 0]
        check_stock(movements + added)  # cannot fail: shipments are capped by the stock
        if new_lines:
            append_lines(files, movements_bytes, new_lines)
        status = order_status(order, shipped_quantities(order, movements + added))
        out = [f"{sku} shipped {ship} backordered {owed}" for sku, ship, owed in plan]
        out.append(f"status {status}")
        return as_lines(out)

    if command == "report":
        rows = []
        ordered_orders = sorted(
            orders, key=lambda o: (o.date, int(o.id[3:]), o.id)
        )
        for order in ordered_orders:
            shipped = shipped_quantities(order, movements)
            invoice = invoice_order(order, movements)
            invoiced = price_order(invoice, catalog).total if invoice.lines else "0.00"
            rows.append(
                {
                    "order": order.id,
                    "date": order.date.isoformat(),
                    "customer": order.customer,
                    "status": order_status(order, shipped),
                    "ordered": sum(q for _, q in order.lines),
                    "shipped": sum(s for _, s in shipped),
                    "quoted": money(price_order(order, catalog).total),
                    "invoiced": money(invoiced),
                }
            )
        if req.format == "json":
            return as_json(rows)
        if req.format == "csv":
            buf = io.StringIO()
            keys = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]
            writer = csv.DictWriter(buf, fieldnames=keys, lineterminator="\n")
            writer.writeheader()
            writer.writerows(rows)
            return buf.getvalue()
        return as_lines(
            f"{r['order']} {r['date']} {r['customer']} {r['status']} "
            f"{r['shipped']}/{r['ordered']} {r['quoted']} {r['invoiced']}"
            for r in rows
        )

    raise UsageError(f"unknown command {command!r}")  # pragma: no cover


